"""
seed_demo.py — populate the database with SYNTHETIC demo data.

Run:  python -m backend.seed_demo

Creates (idempotent — safe to run repeatedly):
  * 2 demo users with completed profiles
  * 1 saved plan each (generated by the rule-based engine)

All data is synthetic. Nothing here is real health information.
"""

import logging

from backend.database import Base, SessionLocal, engine
from backend.models import DietPlan, Profile, User

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("diet.seed")

DEMO_USERS = [
    {
        "name": "Demo Aasha",
        "email": "aasha@demo.com",
        "password": "Demo@12345",
        "profile": {
            "age": 28, "height_cm": 165, "weight_kg": 68,
            "activity_level": "moderate", "dietary_preference": "vegetarian",
            "goal": "weight_loss", "allergies": "nuts", "meals_per_day": 3,
        },
    },
    {
        "name": "Demo Vikram",
        "email": "vikram@demo.com",
        "password": "Demo@12345",
        "profile": {
            "age": 31, "height_cm": 175, "weight_kg": 62,
            "activity_level": "active", "dietary_preference": "non_vegetarian",
            "goal": "weight_gain", "allergies": "", "meals_per_day": 4,
        },
    },
]


def seed() -> None:
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        from backend.ai_engine.diet_engine import get_diet_engine
        from backend.ai_engine.rule_based_engine import UserPreferences
        from backend.cloud.auth_service import hash_password

        for spec in DEMO_USERS:
            user = db.query(User).filter(User.email == spec["email"]).first()
            if user is None:
                user = User(
                    name=spec["name"],
                    email=spec["email"],
                    password_hash=hash_password(spec["password"]),
                )
                db.add(user)
                db.commit()
                db.refresh(user)
                logger.info("Created demo user %s", spec["email"])
            else:
                logger.info("Demo user already exists: %s", spec["email"])

            profile = db.query(Profile).filter(Profile.user_id == user.id).first()
            if profile is None:
                profile = Profile(user_id=user.id, **spec["profile"])
                db.add(profile)
                db.commit()
                logger.info("Created demo profile for %s", spec["email"])

            if not db.query(DietPlan).filter(DietPlan.user_id == user.id).first():
                prefs = UserPreferences(
                    user_id=user.id,
                    **{
                        k: v
                        for k, v in spec["profile"].items()
                        if k not in ("meals_per_day", "allergies")
                    },
                    allergies=[a for a in spec["profile"]["allergies"].split(",") if a],
                )
                result = get_diet_engine().generate(prefs)
                plan = DietPlan(
                    user_id=user.id,
                    title=result.title,
                    breakfast=result.breakfast,
                    lunch=result.lunch,
                    snack=result.snack,
                    dinner=result.dinner,
                    nutrition_summary=result.nutrition_summary,
                    engine_used=result.engine_used,
                    goal=result.goal,
                    dietary_preference=result.dietary_preference,
                )
                db.add(plan)
                db.commit()
                logger.info("Saved demo plan for %s", spec["email"])

        logger.info("Demo data ready. Log in with aasha@demo.com / Demo@12345")
    finally:
        db.close()


if __name__ == "__main__":
    seed()
